(()=>{
 const lessons={
  ar:{name:'埃及阿拉伯语',lang:'ar-EG',phrases:[['السلام عليكم','你好 / 愿你平安','as-salāmu ʿalaykum'],['شكراً','谢谢','shukran'],['من فضلك، إلى هذا العنوان','请带我去这个地址','min faḍlak, ilā hādhā al-ʿunwān']]},
  fr:{name:'法语',lang:'fr-FR',phrases:[['Bonjour','你好','bon-jour'],['Merci','谢谢','mer-si'],['Où est la gare ?','车站在哪里？','ou è la gar']]},
  de:{name:'德语',lang:'de-DE',phrases:[['Guten Tag','你好','gu-ten tak'],['Danke','谢谢','dan-ke'],['Wo ist der Bahnhof?','火车站在哪里？','vo ist der ban-hof']]},
  es:{name:'西班牙语',lang:'es-ES',phrases:[['Hola','你好','o-la'],['Gracias','谢谢','gra-sias'],['¿Dónde está la estación?','车站在哪里？','don-de es-ta la es-ta-sion']]},
  it:{name:'意大利语',lang:'it-IT',phrases:[['Buongiorno','你好','buon-jor-no'],['Grazie','谢谢','gra-tsie'],['Dov’è la stazione?','车站在哪里？','do-ve la sta-tsio-ne']]},
  pt:{name:'葡萄牙语',lang:'pt-PT',phrases:[['Olá','你好','o-la'],['Obrigado / Obrigada','谢谢','o-bri-ga-do / da'],['Onde fica a estação?','车站在哪里？','on-de fi-ka a es-ta-são']]},
  nl:{name:'荷兰语',lang:'nl-NL',phrases:[['Hallo','你好','ha-lo'],['Dank je wel','谢谢','dank ye vel'],['Waar is het station?','车站在哪里？','vaar is het sta-sion']]},
  el:{name:'希腊语',lang:'el-GR',phrases:[['Γεια σας','你好','ya sas'],['Ευχαριστώ','谢谢','ef-ha-ri-sto'],['Πού είναι ο σταθμός;','车站在哪里？','pu ine o stathmos']]},
  ja:{name:'日语',lang:'ja-JP',phrases:[['こんにちは','你好','konnichiwa'],['ありがとうございます','谢谢','arigatō gozaimasu'],['駅はどこですか','车站在哪里？','eki wa doko desu ka']]},
  ko:{name:'韩语',lang:'ko-KR',phrases:[['안녕하세요','你好','annyeonghaseyo'],['감사합니다','谢谢','gamsahamnida'],['역이 어디예요?','车站在哪里？','yeogi eodi-yeyo']]},
  th:{name:'泰语',lang:'th-TH',phrases:[['สวัสดี','你好','sawasdee'],['ขอบคุณ','谢谢','khop khun'],['สถานีรถไฟอยู่ที่ไหน','火车站在哪里？','sathani rotfai yu thi nai']]},
  id:{name:'印尼语',lang:'id-ID',phrases:[['Halo','你好','ha-lo'],['Terima kasih','谢谢','te-ri-ma ka-sih'],['Di mana stasiun?','车站在哪里？','di ma-na sta-siun']]},
  ms:{name:'马来语',lang:'ms-MY',phrases:[['Hai','你好','hai'],['Terima kasih','谢谢','te-ri-ma ka-sih'],['Di mana stesen?','车站在哪里？','di ma-na ste-sen']]},
  en:{name:'旅行英语',lang:'en-US',phrases:[['Hello','你好','he-lo'],['Thank you','谢谢','thank you'],['Please take me to this address.','请带我去这个地址','please take me to this address']]}
 };
 const rules=[[/埃及|开罗|卢克索|吉萨|亚历山大/, 'ar'],[/法国|巴黎|比利时|布鲁塞尔|瑞士|日内瓦/,'fr'],[/德国|奥地利|柏林|慕尼黑|维也纳/,'de'],[/西班牙|巴塞罗那|马德里/,'es'],[/意大利|罗马|米兰|佛罗伦萨|威尼斯/,'it'],[/葡萄牙|里斯本/,'pt'],[/荷兰|阿姆斯特丹/,'nl'],[/希腊|雅典/,'el'],[/日本|东京|京都|大阪/,'ja'],[/韩国|首尔|釜山/,'ko'],[/泰国|曼谷|清迈|普吉/,'th'],[/印尼|印度尼西亚|巴厘岛/,'id'],[/马来西亚|吉隆坡|槟城/,'ms']];
 const language=t=>lessons[(rules.find(([re])=>re.test([t.destination,getDestination(t)?.country].join(' ')))||[])[1]||'en'];
 let recordedAudio;
 const task=t=>{const items=checklistItems(t),by=id=>items.find(x=>x.id===id),needed=['id','visa','entry','transport','hotel','insurance','money','mobile','weather','medicine'];for(const id of needed){const item=by(id);if(item&&!t.checked?.[id])return {title:item.label,why:id==='visa'||id==='entry'?'入境资格需要按官方最新要求核实。':'完成后可在出发清单勾选。',action:'打开清单',kind:'check'}}const missing=(t.days||[]).findIndex(d=>!d.places?.length);if(missing>=0)return {title:`安排第${missing+1}天的地点`,why:'给当天至少加入一个有坐标的地点。',action:'去安排行程',kind:'day'};if((t.languageDone||0)<3&&t.region==='出境')return {title:'学会抵达后的三句话',why:'3分钟轻练习，出发时更从容。',action:'开始语言练习',kind:'language'};return {title:'准备事项已完成',why:'出发前再核对天气、开放信息和订单。',action:'查看清单',kind:'check'}};
 const old=renderTrip;
 renderTrip=function(){const markup=old(),t=trip();if(!t)return markup;const next=task(t),course=language(t),index=Math.min(2,Number(t.languageDone||0)),phrase=course.phrases[index];const widget=`<section class="coach-card" id="next-task"><span class="page-overline">NEXT STEP</span><h2>下一件事</h2><strong>${escapeHtml(next.title)}</strong><p>${escapeHtml(next.why)}</p><button type="button" data-coach="${next.kind}">${escapeHtml(next.action)} ↗</button></section><section class="language-card" id="language-lesson"><div><span class="page-overline">3 MINUTES A DAY</span><h2>开口之前 <small>${escapeHtml(course.name)}</small></h2><p>第 ${index+1} / 3 句 · ${index===2?'学会后可随时回听':'学会一句，再走一步'}</p></div><div class="language-phrase" lang="${course.lang}">${escapeHtml(phrase[0])}</div><p>${escapeHtml(phrase[1])} <small>· ${escapeHtml(phrase[2])}</small></p><div class="language-actions"><button type="button" data-language="speak">听发音</button><button type="button" data-language="learn">${index===2&&t.languageDone>=3?'已学会三句':'我学会了'}</button></div><p class="language-feedback" role="status">${course.lang==='ar-EG'?'旅行用现代埃及阿拉伯语；古埃及文字会留在博物馆讲解里。':''}</p></section>`;return markup.replace('<div class="trip-heading">',`${widget}<div class="trip-heading">`)};
 document.addEventListener('click',e=>{const b=e.target.closest('[data-coach],[data-language]');if(!b)return;const t=trip();if(!t)return;if(b.dataset.coach){if(b.dataset.coach==='check')goto('checklist');else if(b.dataset.coach==='day')document.getElementById('trip-map-workspace')?.scrollIntoView({behavior:'smooth'});else document.getElementById('language-lesson')?.scrollIntoView({behavior:'smooth'});return}if(b.dataset.language==='learn'){t.languageDone=Math.min(3,Number(t.languageDone||0)+1);saveTrip(t);render();notify('已记录，准备环的语言段更新了。');return}const course=language(t),index=Math.min(2,Number(t.languageDone||0)),phrase=course.phrases[index];const feedback=document.querySelector('.language-feedback');if(course.lang==='ar-EG'){recordedAudio?.pause();recordedAudio=new Audio(`audio/ar-${index}.mp3`);recordedAudio.play().then(()=>{feedback.textContent='正在播放埃及阿拉伯语录音，可再点一次重听。'}).catch(()=>{feedback.textContent='录音暂时无法播放，请检查页面音量后重试。'});return}if(!('speechSynthesis' in window)){feedback.textContent='这台设备暂不支持朗读。';return}const voices=speechSynthesis.getVoices(),voice=voices.find(v=>v.lang.toLowerCase().startsWith(course.lang.slice(0,2).toLowerCase()));if(!voice){feedback.textContent='这台设备没有对应语言的语音，暂不朗读以免发音错误。';return}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(phrase[0]);utterance.lang=course.lang;utterance.voice=voice;utterance.rate=.82;speechSynthesis.speak(utterance);feedback.textContent='正在朗读，可再点一次重听。'});
})();
